void deleteDirectoryOnExit(File directory) throws IOException {
    if (!directory.exists()) {
        throw new FileNotFoundException("Directory does not exist: " + directory);
    }

    if (!directory.canRead()) {
        throw new IOException("Directory cannot be read: " + directory);
    }

    File[] files = directory.listFiles();
    if (files != null && files.length > 0) {
        for (File file : files) {
            if (file.isDirectory()) {
                deleteDirectoryOnExit(file);
            } else {
                file.deleteOnExit();
            }
        }
    }

    directory.deleteOnExit();
}

